    /**
     * @param int $gameId
     *
     * @return Game|null
     */
    public function findOneByGameId(int $gameId): ?Game
    {
        return $this->createQueryBuilder('g')
            ->andWhere('g.gameId = :gameId')
            ->setParameter('gameId', $gameId)
            ->getQuery()
            ->getOneOrNullResult();
    }

    /**
     * @return int|null
     */
    public function findHighestGameId(): ?int
    {
        $result = $this->createQueryBuilder('g')
            ->select('MAX(g.gameId)')
            ->getQuery()
            ->getSingleScalarResult();

        return $result ? (int) $result : null;
    }

    /**
     * @return int
     */
    public function countFinishedGames(): int
    {
        return (int) $this->createQueryBuilder('g')
            ->select('COUNT(g.gameId)')
            ->andWhere('g.status = :status')
            ->setParameter('status', GameStatus::Finished)
            ->getQuery()
            ->getSingleScalarResult();
    }

    /**
     * @param int $limit
     * @param int $offset
     *
     * @return Game[]
     */
    public function findFinished(int $limit, int $offset): array
    {
        return $this->createQueryBuilder('g')
            ->andWhere('g.status = :status')
            ->setParameter('status', GameStatus::Finished)
            ->orderBy('g.gameId', 'DESC')
            ->setFirstResult($offset)
            ->setMaxResults($limit)
            ->getQuery()
            ->getResult();
    }

    /**
     * @param list<int> $gameIds
     *
     * @return array<int, int>
     */
    private function findWinnerRoundsByGameIds(array $gameIds): array
    {
        $uniqueGameIds = array_values(array_unique($gameIds));
        if ([] === $uniqueGameIds) {
            return [];
        }

        $rows = $this->getEntityManager()->getConnection()->fetchAllAssociative(
            <<<'SQL'
SELECT
    rt.game_id AS gameId,
    COUNT(DISTINCT r.round_number) AS winnerRounds
FROM round_throws rt
INNER JOIN round r ON r.round_id = rt.round_id
INNER JOIN game g ON g.game_id = rt.game_id AND g.winner_id = rt.player_id
WHERE rt.game_id IN (:gameIds)
GROUP BY rt.game_id
SQL,
            ['gameIds' => $uniqueGameIds],
            ['gameIds' => ArrayParameterType::INTEGER]
        );

        $winnerRoundsByGameId = [];
        foreach ($rows as $row) {
            $winnerRoundsByGameId[(int) $row['gameId']] = (int) $row['winnerRounds'];
        }

        return $winnerRoundsByGameId;
    }

    /**
     * @param mixed $value
     *
     * @return string|null
     */
    private function formatDateTimeValue(mixed $value): ?string
    {
        if ($value instanceof DateTimeInterface) {
            return $value->format(DateTimeInterface::ATOM);
        }

        if (null === $value || '' === $value) {
            return null;
        }

        try {
            return (new DateTimeImmutable((string) $value))->format(DateTimeInterface::ATOM);
        } catch (\Exception) {
            return null;
        }
    }
}
